/* ===== Result statistics (modern / classic view) ===== */
let STV='m';A.stv=()=>{STV=STV=='m'?'c':'m'};
function statCard(Q,ans,used){const n=Q.length,att=Q.filter((x,k)=>ans[k]!==undefined).length,ok=Q.filter((x,k)=>ans[k]===x.a).length,wr=att-ok,sk=n-att,acc=att?Math.round(100*ok/att):0,avg=att?Math.round((used||0)/att):0,bq=Q.filter(x=>!isP(x)).length,tp={};
Q.forEach((x,k)=>{const t=String(x.tp||x.s).replace(/^[^:]*:\s*/,''),r=tp[t]=tp[t]||[0,0];r[1]++;if(ans[k]===x.a)r[0]++});
const rows=Object.entries(tp).map(([t,r])=>[t,r[0],r[1],Math.round(100*r[0]/r[1])]).sort((a,b)=>a[3]-b[3]),
head=`<div class='row'><h3 class='grow'>পরিসংখ্যান</h3><button data-a='stv'>${STV=='m'?'ক্লাসিক':'মডার্ন'} ভিউ</button></div>`,
td="style='border:1px solid var(--bd);padding:.3rem .55rem'";
const base=[['মোট প্রশ্ন',bd(n)],['উত্তর দেওয়া',bd(att)],['সঠিক',bd(ok)],['ভুল',bd(wr)],['বাদ',bd(sk)],['নির্ভুলতা (উত্তর দেওয়াগুলোর মধ্যে)',bd(acc)+'%'],['গড় সময় প্রতি প্রশ্নে',bd(avg)+' সে'],['বোর্ড প্রশ্ন / অনুশীলন',bd(bq)+' / '+bd(n-bq)]];
if(STV=='c')return `<div class='card'>${head}<table style='width:100%;border-collapse:collapse;font-size:.95rem'>${base.map(r=>`<tr><td ${td}>${r[0]}</td><td ${td}><b>${r[1]}</b></td></tr>`).join('')}</table><h3 style='margin-top:1rem'>অধ্যায় অনুযায়ী</h3><table style='width:100%;border-collapse:collapse;font-size:.95rem'><tr><th ${td} align='left'>অধ্যায়</th><th ${td}>সঠিক/মোট</th><th ${td}>%</th></tr>${rows.map(r=>`<tr><td ${td}>${esc(r[0])}</td><td ${td} align='center'>${bd(r[1])}/${bd(r[2])}</td><td ${td} align='center'>${bd(r[3])}%</td></tr>`).join('')}</table></div>`;
return `<div class='card'>${head}<div class='tiles'>${[['সঠিক',ok,'ok'],['ভুল',wr,'err'],['বাদ',sk,''],['নির্ভুলতা',acc+'%',''],['গড় সময়',avg+' সে',''],['বোর্ড প্রশ্ন',bq,'']].map(r=>`<div class='tile'><b class='${r[2]}'>${bd(r[1])}</b><small>${r[0]}</small></div>`).join('')}</div><h3>অধ্যায় অনুযায়ী ফল (দুর্বল আগে)</h3>${rows.map(r=>`<div style='margin:.45rem 0'><div class='row'><span class='grow'>${esc(r[0])}</span><b>${bd(r[1])}/${bd(r[2])}</b></div><div class='bar'><i style='width:${r[3]}%'></i></div></div>`).join('')}</div>`}

/* ===== Custom question count ===== */
document.addEventListener('change',e=>{const i=e.target.id;if(i=='mkq'){const x=Math.round(+e.target.value);if(x>=1)MK.n=x;render()}else if(i=='xqn'){const x=Math.round(+e.target.value);if(x>=1){BX.sn=x;BX.st=0}render()}});

